class OrderManagementSystem:

    def __init__(self):
        # orderId -> (orderType, price) for every active order
        self.orders = {}
        # (orderType, price) -> ids of active orders (dict used as an ordered set)
        self.buckets = {}

    def addOrder(self, orderId, orderType, price):
        # Record the order and put it in its (type, price) bucket
        self.orders[orderId] = (orderType, price)
        key = (orderType, price)
        if key not in self.buckets:
            self.buckets[key] = {}
        self.buckets[key][orderId] = True

    def _remove_from_bucket(self, orderId):
        # Take the id out of its current bucket and drop the bucket if empty
        key = self.orders[orderId]
        del self.buckets[key][orderId]
        if not self.buckets[key]:
            del self.buckets[key]
        return key

    def modifyOrder(self, orderId, newPrice):
        # Remove from the old bucket, then re-add at the new price with the same type
        orderType, _ = self._remove_from_bucket(orderId)
        self.addOrder(orderId, orderType, newPrice)

    def cancelOrder(self, orderId):
        # Remove from its bucket and forget the order entirely
        self._remove_from_bucket(orderId)
        del self.orders[orderId]

    def getOrdersAtPrice(self, orderType, price):
        # Active orders with this type and price (any order is accepted)
        key = (orderType, price)
        if key not in self.buckets:
            return []
        return list(self.buckets[key].keys())
